def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}

    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for chosen in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in chosen))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            # At each start, discard intervals that have already ended; endpoints touch safely.
            active_ends = []
            valid = True
            for job in sorted(chosen, key=lambda item: (item["start"], item["end"], item["id"])):
                active_ends = [end for end in active_ends if end > job["start"]]
                active_ends.append(job["end"])
                if len(active_ends) > 2:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in chosen)
            if (best_value is None or value > best_value
                    or (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << index for index, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bits.get(data["source"], 0)
        source_state = (data["source"], initial_mask, data["coupons"])
        start = data["start"]
        distances = {source_state: start}
        queue = [(start, data["source"], initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(depart + edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((depart + duration, remaining - 1))
                next_mask = mask | bits.get(edge["v"], 0)
                for next_time, next_remaining in choices:
                    if next_time > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, edge["v"], next_mask, next_remaining))
        return {"arrival": None}

    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
    "component_04": _build_component_04(),
    "component_05": _build_component_05(),
    "component_06": _build_component_06(),
    "component_07": _build_component_07(),
    "component_08": _build_component_08(),
}
